package agent;
import components.*;import jade.GameObject;import scenes.Scene;import physics2d.components.*;import physics2d.enums.BodyType;import org.joml.Vector2f;import org.junit.Test;import static org.junit.Assert.*;
public class OpportunityMotion121Test {
 private GameObject body(Scene s,float x,float y,boolean ground){var o=s.createGameObject("fixture");o.transform.position.set(x,y);o.transform.scale.set(.25f,.25f);var b=new Rigidbody2D();b.setBodyType(BodyType.Static);o.addComponent(b);var box=new Box2DCollider();box.setHalfSize(new Vector2f(.25f,.25f));o.addComponent(box);if(ground)o.addComponent(new Ground());s.physics().add(o);s.addGameObjectToScene(o);return o;}
 @Test public void observedReversalInvalidatesNearbyForecastUntilFreshStableWindow(){var s=new Scene(null);var p=body(s,.9f,.625f,false);var e=body(s,3,.625f,false);e.addComponent(new GoombaAI());var b=e.getComponent(Rigidbody2D.class);var m=new OpportunityMotion121();b.setVelocity(new Vector2f(-.6f,0));m.observe(s,1);b.setVelocity(new Vector2f(.6f,0));m.observe(s,2);assertEquals(1,m.observation(true).get("reversals"));assertFalse(m.stableNear(3,.625f,2));assertFalse(m.predictable(s,p,3,120,2));m.observe(s,31);assertFalse(m.stableNear(3,.625f,31));m.observe(s,32);assertTrue(m.stableNear(3,.625f,32));assertThrows(IllegalArgumentException.class,()->m.observe(s,32));e.destroy();m.observe(s,33);assertEquals(0,m.observation(true).get("tracked"));}
 @Test public void nativeWallInvalidatesLinearClearancePrediction(){var s=new Scene(null);var p=body(s,.9f,.625f,false);var e=body(s,3.5f,.625f,false);e.addComponent(new GoombaAI());e.getComponent(Rigidbody2D.class).setVelocity(new Vector2f(-.6f,0));var wall=body(s,3,.625f,true);var m=new OpportunityMotion121();m.observe(s,1);assertFalse(m.predictable(s,p,2.8f,120,1));s.physics().destroyGameObject(wall);assertTrue(m.predictable(s,p,2.8f,120,1));}
 @Test public void returnDisabledPolicyCannotChooseAnOtherwiseSafeRememberedBlock(){var s=new Scene(null);for(int i=0;i<24;i++)body(s,i*.25f,.375f,true);var p=body(s,3.2f,.625f,false);var pc=new PlayerController();pc.onGround=true;p.addComponent(pc);var b=s.createGameObject("block");b.transform.position.set(2,1.375f);b.addComponent(new com.google.gson.Gson().fromJson("{\"blockType\":\"Powerup\"}",QuestionBlock.class));s.addGameObjectToScene(b);var planner=new PowerupPlanner();planner.defer(new PowerupPlanner.Goal(PowerupPlanner.Kind.BUMP_BLOCK,b,2,1.375f,"deferred"),0);var normal=planner.step(s,p,20,61);assertTrue(PickupOpportunity120.returnSafe(s,p,b));assertEquals(PowerupPlanner.Kind.TRAVEL,new PickupOpportunity120(true,false).choose(s,p,planner,normal,20,61).kind());assertEquals(b,new PickupOpportunity120(true,true).choose(s,p,planner,normal,20,61).object());}
}
